import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicReferenceFieldUpdater;

public class ConcurrentTypeDispatcher {

    // Polymorphic event hierarchy
    public interface Event {}
    public static class TelemetryEvent implements Event {
        public final double metric = 42.0; // Widened implicitly from float/int if needed
    }
    public static class ControlEvent implements Event {
        public final String command = "SHUTDOWN";
    }

    // Volatile field for atomic updates
    private volatile Event currentEvent = new TelemetryEvent();

    // Atomic updater enforcing runtime type safety via reflection
    private static final AtomicReferenceFieldUpdater<ConcurrentTypeDispatcher, Event> UPDATER =
        AtomicReferenceFieldUpdater.newUpdater(ConcurrentTypeDispatcher.class, Event.class, "currentEvent");

    private final BlockingQueue<Object> rawQueue = new LinkedBlockingQueue<>();

    public void enqueue(Object payload) {
        rawQueue.offer(payload);
    }

    public void processQueue() {
        ExecutorService executor = Executors.newSingleThreadExecutor();
        executor.submit(() -> {
            try {
                while (!Thread.currentThread().isInterrupted()) {
                    Object rawItem = rawQueue.take();

                    // Safe narrowing pattern matching (Java 17+) to prevent ClassCastException
                    if (rawItem instanceof TelemetryEvent telemetry) {
                        // Widening primitive conversion: double to double (implicit)
                        double value = telemetry.metric;
                        System.out.println("Processed telemetry: " + value);
                    } else if (rawItem instanceof ControlEvent control) {
                        System.out.println("Processed control: " + control.command);
                    } else {
                        // Defensive handling of unexpected types that would cause ClassCastException
                        System.err.println("Rejected incompatible type: " + rawItem.getClass().getName());
                    }
                } 
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });
        executor.shutdown();
    }
}
